    .and_then(|outcome| outcome);
    let object = match object {
        Ok(object) => object,
        Err(error) => {
            CURRENT_TARGETS.with(|targets| {
                targets.borrow_mut().remove(&token);
            });
            return Err(error);
        }
    };

    Ok(CurrentCallback {
        object,
        owner,
        target: Some(target),
        token,
        callback_id,
        creator,
        closed: Cell::new(false),
        _not_send: PhantomData,
    })
}

